mapper.select:
SELECT q.id FROM question q JOIN category c ON c.id = q.category_id
AND q.id NOT IN
#{eid}
ORDER BY RAND() LIMIT #{size}

SELECT qt.question_id, t.id AS tag_id, t.name AS tag_name FROM question_tag qt JOIN tag t ON t.id = qt.tag_id WHERE qt.question_id IN
#{id}
ORDER BY qt.question_id ASC, t.id ASC

WITH ordered AS ( SELECT q.id AS id, ROW_NUMBER() OVER (
ORDER BY DESC,
q.practice_count DESC, q.id DESC q.difficulty ASC, q.id ASC q.published_at DESC, q.id DESC
ORDER BY q.practice_count DESC, q.id DESC ORDER BY q.difficulty ASC, q.id ASC ORDER BY q.published_at DESC, q.id DESC
) AS rn FROM question q JOIN category c ON c.id = q.category_id
) SELECT (SELECT id FROM ordered WHERE rn = (SELECT rn FROM ordered WHERE id = #{id}) - 1) AS prev_id, (SELECT id FROM ordered WHERE rn = (SELECT rn FROM ordered WHERE id = #{id}) + 1) AS next_id

WITH ordered AS ( SELECT w.question_id AS id, ROW_NUMBER() OVER (
ORDER BY w.mastered_at DESC, w.id DESC ORDER BY w.due_at ASC, w.id DESC ORDER BY w.updated_at DESC, w.id DESC ORDER BY w.due_at ASC, w.last_wrong_at DESC, w.id DESC
) AS rn FROM wrong_record w JOIN question q ON q.id = w.question_id AND q.deleted = 0 AND q.status = 1 JOIN category c ON c.id = q.category_id AND c.status = 1 WHERE w.user_id = #{userId}
AND w.resolved = 0 AND w.resolved = 1 AND w.due_at IS NOT NULL AND w.review_streak < 4 AND w.review_streak >= 4 AND w.resolved = 1
) SELECT (SELECT id FROM ordered WHERE rn = (SELECT rn FROM ordered WHERE id = #{id}) - 1) AS prev_id, (SELECT id FROM ordered WHERE rn = (SELECT rn FROM ordered WHERE id = #{id}) + 1) AS next_id

SELECT q.id, q.title, q.category_id, c.name AS category_name,
       q.difficulty, q.view_count, q.practice_count, q.published_at
FROM question q
JOIN category c ON c.id = q.category_id
WHERE q.status = 1 AND q.deleted = 0 AND c.status = 1 AND q.id != #{id}
  AND (
    q.category_id = #{categoryId}
    OR EXISTS (
      SELECT 1 FROM question_tag a
      JOIN question_tag b ON b.tag_id = a.tag_id
      WHERE a.question_id = #{id} AND b.question_id = q.id
    )
  )
ORDER BY (q.category_id = #{categoryId}) DESC, q.practice_count DESC, q.id DESC
LIMIT #{limit}

SELECT q.id AS id, q.title AS title, q.difficulty AS difficulty, q.category_id AS category_id, c.name AS category_name, v.last_viewed_at AS last_viewed_at FROM question_view v JOIN question q ON q.id = v.question_id JOIN category c ON c.id = q.category_id WHERE v.user_id = #{userId} AND q.deleted = 0 AND q.status = 1 AND c.status = 1
AND q.category_id = #{categoryId}
ORDER BY v.last_viewed_at DESC, q.id DESC LIMIT #{limit}
